  <div class="card"><div class="table-container"><table class="custom-table"><thead><tr><th>Ngày</th><th>Khoa điều trị</th><th style="text-align:right">Đầu ngày</th><th style="text-align:right">Nhập viện</th><th style="text-align:right">Ra viện</th><th style="text-align:right">Cuối ngày</th><th style="text-align:right">Ngày điều trị</th><th style="text-align:right">Giường dùng</th><th style="text-align:right">Công suất</th><th style="text-align:center">Thao tác</th></tr></thead><tbody><?php if (!$records): ?><tr><td colspan="10" style="text-align:center;padding:38px;color:var(--text-muted)"><i class="fa-regular fa-folder-open" style="display:block;font-size:28px;margin-bottom:10px"></i>Chưa có số liệu phù hợp.</td></tr><?php endif; foreach($records as $r): ?><tr><td style="font-weight:600;white-space:nowrap"><?php echo date('d/m/Y', strtotime($r->full_date)); ?></td><td><?php echo ie($r->department_name); ?></td><td style="text-align:right"><?php echo number_format($r->inpatient_opening_patient_count); ?></td><td style="text-align:right"><?php echo number_format($r->inpatient_admission_count); ?></td><td style="text-align:right"><?php echo number_format($r->inpatient_inpatient_daily_discharge_count); ?></td><td style="text-align:right;font-weight:600"><?php echo number_format($r->inpatient_closing_patient_count); ?></td><td style="text-align:right"><?php echo number_format($r->inpatient_treatment_days); ?></td><td style="text-align:right"><?php echo number_format($r->inpatient_occupied_beds); ?></td><td style="text-align:right"><?php echo $r->bed_occupancy_percent === null ? '—' : ie($r->bed_occupancy_percent) . '%'; ?></td><td><div class="action-btns" style="justify-content:center"><a class="btn-icon" title="Sửa" href="<?php echo XC_URL; ?>/backend/inpatient/edit/<?php echo (int)$r->id; ?>"><i class="fa-solid fa-pen"></i></a><button type="button" class="btn-icon delete" title="Xóa" data-id="<?php echo (int)$r->id; ?>"><i class="fa-solid fa-trash"></i></button></div></td></tr><?php endforeach; ?></tbody></table></div></div>
