<script>$('.btn-icon.delete').on('click',function(){var button=$(this),id=button.data('id');Swal.fire({title:'Xóa bản ghi?',text:'Bản ghi sẽ được chuyển sang trạng thái đã xóa.',icon:'warning',showCancelButton:true,confirmButtonText:'Xóa',cancelButtonText:'Hủy'}).then(function(result){if(!result.isConfirmed)return;button.prop('disabled',true);$.ajax({url:'<?php echo XC_URL; ?>/api/deleteInpatient',type:'POST',dataType:'json',data:{csrf:'<?php echo ie($csrf); ?>',id:id}}).done(function(res){Swal.fire({icon:res.success?'success':'error',title:res.success?'Thành công':'Không thành công',text:res.message,timer:1600,showConfirmButton:false}).then(function(){if(res.success)location.reload();});}).fail(function(xhr){Swal.fire('Không thành công',(xhr.responseJSON&&xhr.responseJSON.message)||'Không thể xóa bản ghi. Vui lòng thử lại.','error');}).always(function(){button.prop('disabled',false);});});});</script>
